UPDATE ai_mcp
mcp_id = #{mcpId}, mcp_name = #{mcpName}, mcp_type = #{mcpType}, mcp_param = #{mcpParam}, mcp_secret = #{mcpSecret}, mcp_desc = #{mcpDesc}, mcp_timeout = #{mcpTimeout},
